package dev.wowforever.importer.acquisition;
import static org.assertj.core.api.Assertions.*;
import java.nio.*;import java.nio.charset.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class ItemSparseHotfixDecoderTest {
 @TempDir Path temporary;
 private static final String DEFINITION="COLUMNS\nint ID\nlocstring Name_lang\nint Signed\nint Unsigned\nfloat Ratio\nint Flags\n\nLAYOUT TEST0001\nBUILD 1.60.1.70450\n$noninline,id$ID<32>\nName_lang\nSigned<8>\nUnsigned<u32>\nRatio\nFlags<u16>[2]\n";
 PinnedItemSparseDefinition definition()throws Exception{return PinnedItemSparseDefinition.parseDefinition(DEFINITION.getBytes(UTF_8),"1.60.1.70450","TEST0001");}
 private static final Charset UTF_8=StandardCharsets.UTF_8;
 byte[] payload(){return ByteBuffer.allocate(16).order(ByteOrder.LITTLE_ENDIAN).put("Hi".getBytes(UTF_8)).put((byte)0).put((byte)-8).putInt(-1).putFloat(1.25f).putShort((short)7).putShort((short)65535).array();}
 @Test void authoredSchemaDecodesSignedUnsignedFloatStringsArraysAndNoninlineIdentity()throws Exception{var row=ItemSparseHotfixDecoder.decodeRecord(definition(),payload(),4294967295L);assertThat(row).containsEntry("ID",4294967295L).containsEntry("Name_lang","Hi").containsEntry("Signed",-8L).containsEntry("Unsigned",4294967295L).containsEntry("Ratio",1.25f).containsEntry("Flags_0",7L).containsEntry("Flags_1",65535L);assertThatThrownBy(()->row.put("ID",1)).isInstanceOf(UnsupportedOperationException.class);}
 @Test void productionDefinitionPinCannotBeBypassedByAuthoredFixture(){assertThatThrownBy(()->PinnedItemSparseDefinition.parse(DEFINITION.getBytes(UTF_8))).hasMessageContaining("SHA-256");}
 @Test void unsupportedWrongOrAmbiguousLayoutsFail()throws Exception{assertThatThrownBy(()->PinnedItemSparseDefinition.parseDefinition(DEFINITION.getBytes(UTF_8),"1.60.1.70451","TEST0001")).hasMessageContaining("absent");assertThatThrownBy(()->PinnedItemSparseDefinition.parseDefinition(DEFINITION.getBytes(UTF_8),"1.60.1.70450","BAD")).hasMessageContaining("layout hash");String extra=DEFINITION+"\nLAYOUT TEST0001\nBUILD 1.60.1.70450\n$noninline,id$ID<32>\n";assertThatThrownBy(()->PinnedItemSparseDefinition.parseDefinition(extra.getBytes(UTF_8),"1.60.1.70450","TEST0001")).hasMessageContaining("Ambiguous");}
 @Test void unsupportedRelationsIntegersAndArraysFail()throws Exception{for(String bad:List.of(DEFINITION.replace("noninline,id","noninline,relation"),DEFINITION.replace("Signed<8>","Signed<64>"),DEFINITION.replace("Flags<u16>[2]","Flags<u16>[1000]"))){assertThatThrownBy(()->PinnedItemSparseDefinition.parseDefinition(bad.getBytes(UTF_8),"1.60.1.70450","TEST0001")).isInstanceOf(java.io.IOException.class);}}
 @Test void missingUtf8TerminatorAndInvalidUtf8AreRefused()throws Exception{byte[] unterminated=new byte[20];Arrays.fill(unterminated,(byte)65);assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),unterminated,1)).hasMessageContaining("Unterminated");byte[] invalid=payload();invalid[0]=(byte)0xc0;assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),invalid,1)).hasMessageContaining("UTF-8");}
 @Test void truncatedOrTrailingPayloadBytesAreRefused()throws Exception{assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),Arrays.copyOf(payload(),15),1)).hasMessageContaining("Truncated");assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),Arrays.copyOf(payload(),17),1)).hasMessageContaining("Unconsumed");}
 @Test void nonfiniteFloatAndOversizedPayloadAreRefused()throws Exception{byte[] bytes=payload();ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN).putFloat(8,Float.NaN);assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),bytes,1)).hasMessageContaining("Nonfinite");assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeRecord(definition(),new byte[1_048_577],1)).hasMessageContaining("limit");}
 @Test void orderedEventLedgerRetainsDuplicatesTombstonesAndInvalidationsWithoutResolving()throws Exception{byte[] valid=payload();var events=List.of(entry(0,100,HotfixSnapshotReader.Status.VALID,valid.length),entry(1,2,HotfixSnapshotReader.Status.REMOVED,0),entry(2,99,HotfixSnapshotReader.Status.INVALIDATED,0),entry(3,1,HotfixSnapshotReader.Status.NOT_PUBLIC,0),entry(4,3,HotfixSnapshotReader.Status.VALID,valid.length));var structure=new HotfixSnapshotReader.Snapshot(9,70450,"opaque",events);var decoded=ItemSparseHotfixDecoder.decodeEvents(definition(),structure,valid,()->false);assertThat(decoded).hasSize(5);assertThat(decoded).extracting(e->e.source().push()).containsExactly(100,2,99,1,3);assertThat(decoded).extracting(e->e.source().region()).containsOnly(70);assertThat(decoded.get(0).values()).isEqualTo(decoded.get(4).values());assertThat(decoded.subList(1,4)).allSatisfy(e->assertThat(e.values()).isEmpty());assertThatThrownBy(()->decoded.clear()).isInstanceOf(UnsupportedOperationException.class);}
 @Test void unselectedTableSkippedButOriginalSequenceRetained()throws Exception{var other=new HotfixSnapshotReader.Entry(0,70,1,2,123,50,0,0,HotfixSnapshotReader.Status.VALID);var structure=new HotfixSnapshotReader.Snapshot(9,70450,"opaque",List.of(other,entry(1,1,HotfixSnapshotReader.Status.VALID,payload().length)));var result=ItemSparseHotfixDecoder.decodeEvents(definition(),structure,payload(),()->false);assertThat(result).hasSize(1);assertThat(result.getFirst().snapshotSequence()).isEqualTo(1);}
 @Test void cancellationDoesNotReturnPartialLedger()throws Exception{var structure=new HotfixSnapshotReader.Snapshot(9,70450,"opaque",List.of(entry(0,1,HotfixSnapshotReader.Status.VALID,payload().length)));assertThatThrownBy(()->ItemSparseHotfixDecoder.decodeEvents(definition(),structure,payload(),()->true)).isInstanceOf(CancellationException.class);}
 private HotfixSnapshotReader.Entry entry(int order,int push,HotfixSnapshotReader.Status status,int bytes){return new HotfixSnapshotReader.Entry(order,70,push,1,ItemSparseHotfixDecoder.TABLE_HASH,42,0,bytes,status);}
}
